def flatten(obj,prefix=''):
    rows=[]
    if isinstance(obj,dict):
        for k,v in obj.items():rows+=flatten(v,prefix+k+' / ')
    elif isinstance(obj,(float,int,str,bool)):
        rows.append((prefix.rstrip(' / '),f'{obj:.12g}' if isinstance(obj,float) else str(obj)))
    elif isinstance(obj,list) and len(str(obj))<250:rows.append((prefix.rstrip(' / '),str(obj)))
    return rows

def main():
    catalog={e['id']:e for e in json.loads((ROOT/'coverage/worked_examples.json').read_text())['entries']};entries=[]
    for id,(module,model,kind) in MODELS.items():
        path=ROOT/'artifacts/examples'/id/'results.json'
        if not path.exists():continue
        r=json.loads(path.read_text());e=dict(catalog[id]);
        if id=='fig_7_1':e['data_availability']='The official logreg.bin file and both companion scripts contain100 observations. This corrects the earlier inventory count of50.'
        if id=='example_8_6':e['data_availability']='The companion placement.bin publishes eight fixed points, six free points and28 edges, explicitly different from the book’s27-edge instance.'
        if id=='example_6_4':e['data_availability']='The10-by-20 matrix and response are published in regsel.bin; regsel.py explicitly states that they differ from the book.'
        doc=ROOT/'docs/examples'/(id+'.md');code=ROOT/'examples'/module
        text=f'# {id.replace("_"," ")}: {e["title"]}\n\n'
        text+=('**Exact-input reproduction.** Uses the printed instance or the named official numerical data. Numerical precision and drawing style can differ from the source.\n\n' if kind=='exact' else '**Method reproduction, approved substitute data or source convention.** This is not an exact recreation of the book’s random realization or figure. The specific differences are documented below.\n\n')
        text+=f'[Textbook source]({e["source_url"]}) · [Original Python](../../examples/{module}) · [Executed JSON](../../artifacts/examples/{id}/results.json) · [Tests](../../tests/test_worked_applications.py)\n\n## Model and verification\n\n{model}\n\n## Inputs and source comparison\n\n{e["data_availability"]}\n\n'
        for url in e['official_code_urls']:text+=f'- [Official reference]({url})\n'
        for d in e['official_data_files']:text+=f'- [{d["url"].split("/")[-1]}]({d["url"]}), SHA-256 `{d["sha256"]}`\n'
        for note in r.get('caveats',[]):text+=f'- {note}\n'
        text+='\nThe implementation is original Python. Reused numeric data are attributed separately in `data/worked_examples`, including conversion hashes and the upstream GPL-3.0-or-later notice. No textbook scans or reference program bodies are redistributed.\n\n'
        text+=f'## Executed results\n\nRun at {r["executed_at"]}; Python {r["python"]}; NumPy {r["numpy"]}; CVXPY {r["cvxpy"]}; elapsed {r["elapsed_seconds"]:.3f} s.\n\n| Quantity | Actual value |\n| --- | --- |\n'
        for k,v in flatten(r['summary']):text+=f'| {k} | {v} |\n'
        if 'cases' in r and isinstance(r['cases'],list):
            text+='\n| Case | Delta | Eta | Tracking | Magnitude | Derivative | Objective |\n| --- | --- | --- | --- | --- | --- | --- |\n'
            for i,c in enumerate(r['cases'],1):text+=f'| {i} | {c["delta"]} | {c["eta"]} | {c["terms"]["tracking"]:.10g} | {c["terms"]["magnitude"]:.10g} | {c["terms"]["derivative"]:.10g} | {c["objective"]:.10g} |\n'
        text+='\n## Numerical checks\n\n| Check | Measured error | Acceptance limit |\n| --- | --- | --- |\n'
        for c in r['checks']:text+=f'| {c["name"]} | {c["measured"]:.6g} | {c["tolerance"]:.6g} |\n'
        text+='\n## Recomputed figures\n\n'
        for plot in r['plots']:text+=f'![{e["title"]}: {plot}](../../artifacts/examples/{id}/{plot})\n\n'
        text+=f'## Reproduce\n\n```sh\nOPENBLAS_NUM_THREADS=1 python examples/{module} {id}\npython -m pytest tests/test_worked_applications.py -q\n```\n'
        doc.write_text(text)
        entries.append({'id':id,'title':e['title'],'solution_path':str(doc.relative_to(ROOT)),'code_path':str(code.relative_to(ROOT)),'results_path':str(path.relative_to(ROOT)),'source_url':e['source_url'],'source_checked':True,'all_subparts_completed':True,'solution_sha256':hashlib.sha256(doc.read_bytes()).hexdigest(),'reproduction_basis':model,'reproduction_kind':kind,'output_match_verified':kind=='exact','verification':{'test_command':f'OPENBLAS_NUM_THREADS=1 python examples/{module} {id}; python -m pytest tests/test_worked_applications.py -q','test_result':'passed executed embedded mathematical/independent-solver assertions','independent_checks':r['checks']},'supporting_paths':sorted(set(list(r.get('runtime_source_sha256',{}))+list(r.get('input_file_sha256',{}))+[p.replace('.json','.provenance.json') for p in r.get('input_file_sha256',{})]+['data/worked_examples/LICENSE-CVXOPT-DATA.txt','data/worked_examples/README.md','tests/test_worked_applications.py','scripts/render_application_studies.py','scripts/prepare_worked_example_data.py']+[str((path.parent/name).relative_to(ROOT)) for name in r['plots']])), 'notes':r.get('caveats',[])})
    dest=ROOT/'coverage/submissions/examples_ch04_08.json';dest.write_text(json.dumps({'schema_version':1,'author':'reproduce_application_worked_examples','entries':entries},indent=2)+'\n');print('Rendered',len(entries))
if __name__=='__main__':main()
